import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    public static BigInteger A(int n, int k) {
        return factorial(n).divide(factorial(n - k));
    }

    public static void execute() {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        String[] parts = line.trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int mod = Integer.parseInt(parts[1]);
        if (n == 1) {
            System.out.println(0);
            return;
        }
        int[] zArray = new int[1];
        zArray[0] = 1;
        long totalSum = 0;
        for (int i = 2; i <= n; i++) {
            int size = (i * i) / 2;
            int[] nextZArray = new int[size];
            for (int j = 0; j < zArray.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (zArray[j] > 0) {
                        int index = i - k - 1 + j;
                        if (index >= 0 && index < size) {
                            nextZArray[index] += zArray[j];
                        }
                    }
                }
            }
            int[] prefixArray = new int[zArray.length + 1];
            for (int w = zArray.length - 1; w >= 0; w--) {
                prefixArray[w] = (prefixArray[w + 1] + zArray[w]) % mod;
            }
            int[] eVals = new int[prefixArray.length];
            int[] fVals = new int[prefixArray.length];
            for (int w = 0; w < prefixArray.length - 1; w++) {
                eVals[w + 1] = (eVals[w] + prefixArray[w]) % mod;
                fVals[w + 1] = (fVals[w] - w * prefixArray[w]) % mod;
            }
            long tempSum = 0;
            for (int jj = 0; jj < zArray.length; jj++) {
                int L = jj + 2;
                int R = Math.min(zArray.length - 1, i + jj);
                long ccc = 0;
                if (R >= L) {
                    long eDiff = (long) eVals[R + 1] - eVals[L];
                    long fDiff = (long) fVals[R + 1] - fVals[L];
                    ccc = ((eDiff * (i + 1 + jj)) % mod + fDiff) % mod;
                }
                totalSum = (totalSum + ccc * zArray[jj]) % mod;
            }
            BigInteger totalSumBig = BigInteger.valueOf(totalSum);
            BigInteger aVal = A(n, n - i);
            totalSum = totalSumBig.add(totalSumBig.multiply(aVal)).mod(BigInteger.valueOf(mod)).longValue();
            zArray = nextZArray;
        }
        System.out.println(totalSum % mod);
        scanner.close();
    }

    public static void main(String[] args) {
        execute();
    }
}

